//! Binary Rust `nve-dioxus` + `nve-abi` binary emitter for `import_rn`.

mod types;

use crate::writer::CodeWriter;

use crate::naming::{
    escape_c_like_string, rust_ident, sanitize_single_line_comment, strip_on_prefix,
    to_pascal_case, to_snake_case,
};
use crate::schema::export::{RnComponentSpec, TurboModuleSpec};
use types::*;

pub(crate) fn emit_component_rust(spec: &RnComponentSpec, mod_name: &str) -> String {
    let pascal = to_pascal_case(&spec.component_name);
    let mut out = CodeWriter::with_capacity(4096);

    writeln!(
        out,
        "// @generated by nve-codegen (`import_rn`) from React Native Fabric component `{}`.",
        sanitize_single_line_comment(&spec.component_name)
    );
    writeln!(
        out,
        "// Zero-JS, binary FFI typed Rust `nve-dioxus` bindings + `nve-abi` binary prop builders."
    );
    writeln!(out);
    writeln!(out, "#![allow(dead_code, clippy::all)]");
    writeln!(out);
    writeln!(out, "pub mod {mod_name} {{");
    writeln!(
        out,
        "    use nve_abi::{{encode_bin_value_to_vec, BinValueView, ColorRgba, DecodeError, NveMapEntry, NveValue, NveValueRef, ValidatedEvent}};"
    );
    writeln!(out, "    use nve_dioxus::elements::AttributeDescription;");
    writeln!(out);
    writeln!(
        out,
        "    /// React Native Fabric component name registered in the native host."
    );
    writeln!(
        out,
        "    pub const COMPONENT_NAME: &str = \"{}\";",
        escape_c_like_string(&spec.component_name)
    );
    writeln!(out, "    pub const TAG_NAME: &'static str = COMPONENT_NAME;");
    writeln!(out, "    pub const NAME_SPACE: Option<&'static str> = None;");
    if let Some(paper) = &spec.options.paper_component_name {
        writeln!(
            out,
            "    pub const PAPER_COMPONENT_NAME: &str = \"{}\";",
            escape_c_like_string(paper)
        );
    }
    writeln!(out);

    // 1. Emit auxiliary enums/structs for enum & object props
    for prop in &spec.props {
        emit_rust_aux_types(
            &mut out,
            &pascal,
            &prop.name,
            &prop.prop_type,
            prop.default_value.as_ref(),
        );
    }

    // 2. Emit typed event payload structs + unified component event enum (binary NveBinValue)
    for ev in &spec.events {
        emit_rust_event_payload(&mut out, &pascal, ev);
    }

    if !spec.events.is_empty() {
        writeln!(out, "    #[derive(Debug, Clone, PartialEq)]");
        writeln!(out, "    pub enum {pascal}Event {{");
        for ev in &spec.events {
            let variant = to_pascal_case(&strip_on_prefix(&ev.name));
            if ev.payload.is_empty() {
                writeln!(out, "        {variant},");
            } else {
                let payload_ty = format!("{pascal}{variant}Event");
                writeln!(out, "        {variant}({payload_ty}),");
            }
        }
        writeln!(out, "    }}");
        writeln!(out);

        writeln!(
            out,
            "    /// Decodes a custom binary `NveBinValue` event emitted by `{}` into `{pascal}Event`.",
            sanitize_single_line_comment(&spec.component_name)
        );
        writeln!(
            out,
            "    pub fn decode_event(event: ValidatedEvent<'_>) -> Option<{pascal}Event> {{"
        );
        writeln!(out, "        let name = event.custom_name()?;");
        writeln!(out, "        let data = event.custom_data()?;");
        writeln!(out, "        match name {{");
        for ev in &spec.events {
            let variant = to_pascal_case(&strip_on_prefix(&ev.name));
            let short_name = strip_on_prefix(&ev.name);
            let pattern = if let Some(paper) = &ev.paper_top_level_name {
                format!(
                    "\"{}\" | \"{}\" | \"{}\"",
                    escape_c_like_string(&ev.name),
                    escape_c_like_string(&short_name),
                    escape_c_like_string(paper)
                )
            } else {
                format!(
                    "\"{}\" | \"{}\"",
                    escape_c_like_string(&ev.name),
                    escape_c_like_string(&short_name)
                )
            };
            if ev.payload.is_empty() {
                writeln!(
                    out,
                    "            {pattern} => Some({pascal}Event::{variant}),"
                );
            } else {
                let payload_ty = format!("{pascal}{variant}Event");
                writeln!(
                    out,
                    "            {pattern} => {payload_ty}::decode_bin(data).map({pascal}Event::{variant}),"
                );
            }
        }
        writeln!(out, "            _ => None,");
        writeln!(out, "        }}");
        writeln!(out, "    }}");
        writeln!(out);
    }

    // 3. Emit `dioxus_elements` attribute constants
    writeln!(out, "    /// Attribute descriptors for Dioxus `rsx!{{}}` templates.");
    writeln!(out, "    pub mod attrs {{");
    writeln!(out, "        use super::AttributeDescription;");
    if spec.extends_view_props {
        writeln!(
            out,
            "        pub const nve_style: AttributeDescription = (\"nve_style\", None, false);"
        );
        writeln!(
            out,
            "        pub const test_id: AttributeDescription = (\"testID\", None, false);"
        );
    }
    for prop in &spec.props {
        let ident = rust_ident(&prop.name);
        writeln!(
            out,
            "        #[allow(non_upper_case_globals)]\n        pub const {ident}: AttributeDescription = (\"{}\", None, false);",
            escape_c_like_string(&prop.name)
        );
    }
    writeln!(out, "    }}");
    writeln!(out);

    // 4. Emit typed Dioxus event listener helpers
    if !spec.events.is_empty() {
        writeln!(out, "    /// Typed Dioxus event attribute constructors.");
        writeln!(out, "    pub mod events {{");
        writeln!(out, "        use super::*;");
        writeln!(
            out,
            "        use nve_dioxus::prelude::dioxus_core::{{Attribute, AttributeValue, Event}};"
        );
        for ev in &spec.events {
            let fn_name = rust_ident(&ev.name);
            let variant = to_pascal_case(&strip_on_prefix(&ev.name));
            let event_ty = if ev.payload.is_empty() {
                "Event<()>".to_owned()
            } else {
                format!("Event<{pascal}{variant}Event>")
            };
            writeln!(out);
            writeln!(
                out,
                "        pub fn {fn_name}(handler: impl FnMut({event_ty}) + 'static) -> Attribute {{"
            );
            writeln!(
                out,
                "            Attribute::new(\"{}\", AttributeValue::listener(handler), None, false)",
                escape_c_like_string(&ev.name)
            );
            writeln!(out, "        }}");
        }
        writeln!(out, "    }}");
        writeln!(out);
    }

    // 5. Emit typed Props struct + builder methods + binary NveBinValue encoder
    writeln!(out, "    #[derive(Debug, Clone, PartialEq, Default)]");
    writeln!(out, "    pub struct {pascal}Props {{");
    for prop in &spec.props {
        if let Some(doc) = &prop.doc {
            for line in doc.lines() {
                writeln!(out, "        /// {}", sanitize_single_line_comment(line));
            }
        }
        let field = rust_ident(&prop.name);
        let ty = rust_prop_type(&pascal, &prop.name, &prop.prop_type);
        if prop.optional || prop.nullable {
            writeln!(out, "        pub {field}: Option<{ty}>,");
        } else {
            writeln!(out, "        pub {field}: {ty},");
        }
    }
    writeln!(out, "    }}");
    writeln!(out);

    writeln!(out, "    impl {pascal}Props {{");
    writeln!(out, "        pub fn new() -> Self {{");
    writeln!(out, "            Self::default()");
    writeln!(out, "        }}");

    for prop in &spec.props {
        let field = rust_ident(&prop.name);
        let method = format!("with_{}", to_snake_case(&prop.name));
        let ty = rust_prop_type(&pascal, &prop.name, &prop.prop_type);
        writeln!(out);
        if prop.optional || prop.nullable {
            writeln!(
                out,
                "        pub fn {method}(mut self, value: impl Into<{ty}>) -> Self {{"
            );
            writeln!(out, "            self.{field} = Some(value.into());");
            writeln!(out, "            self");
            writeln!(out, "        }}");
        } else {
            writeln!(
                out,
                "        pub fn {method}(mut self, value: impl Into<{ty}>) -> Self {{"
            );
            writeln!(out, "            self.{field} = value.into();");
            writeln!(out, "            self");
            writeln!(out, "        }}");
        }
    }

    writeln!(out);
    writeln!(
        out,
        "        /// Encodes all configured props for `{}` as a compact binary `NveBinValue` map.",
        sanitize_single_line_comment(&spec.component_name)
    );
    writeln!(out, "        pub fn encode_props(&self) -> Result<Vec<u8>, DecodeError> {{");
    // Phase 1: materialize any nested binary buffers as immutable local bindings before building
    // `NveMapEntry` raw pointers (prevents Vec reallocation / Stacked Borrows invalidation).
    for prop in &spec.props {
        let field = rust_ident(&prop.name);
        if let Some(prep) = rust_prop_preencode_stmt(&field, &prop.prop_type, prop.optional || prop.nullable) {
            writeln!(out, "            {prep}");
        }
    }
    writeln!(
        out,
        "            let mut entries: Vec<NveMapEntry> = Vec::with_capacity({});",
        spec.props.len()
    );
    for prop in &spec.props {
        let field = rust_ident(&prop.name);
        let key = escape_c_like_string(&prop.name);
        if prop.optional || prop.nullable {
            if rust_prop_needs_preencode(&prop.prop_type) {
                writeln!(out, "            if let Some(ref b) = _bin_{field} {{");
                writeln!(
                    out,
                    "                entries.push(NveMapEntry::new(\"{key}\", NveValue::from_bytes(b)));"
                );
                writeln!(out, "            }}");
            } else {
                let expr = rust_prop_to_nve_value_expr("val", &field, &prop.prop_type, true);
                writeln!(out, "            if let Some(ref val) = self.{field} {{");
                writeln!(
                    out,
                    "                entries.push(NveMapEntry::new(\"{key}\", {expr}));"
                );
                writeln!(out, "            }}");
            }
        } else if rust_prop_needs_preencode(&prop.prop_type) {
            writeln!(
                out,
                "            entries.push(NveMapEntry::new(\"{key}\", NveValue::from_bytes(&_bin_{field})));"
            );
        } else {
            let expr =
                rust_prop_to_nve_value_expr(&format!("self.{field}"), &field, &prop.prop_type, false);
            writeln!(
                out,
                "            entries.push(NveMapEntry::new(\"{key}\", {expr}));"
            );
        }
    }
    writeln!(
        out,
        "            let map_val = NveValue::map(&entries);"
    );
    writeln!(
        out,
        "            encode_bin_value_to_vec(unsafe {{ NveValueRef::from_raw(&map_val) }})"
    );
    writeln!(out, "        }}");
    writeln!(out, "    }}");

    // 6. Native Commands (encoded as compact binary `NveBinValue` payloads for `Transaction::command`)
    if !spec.commands.is_empty() {
        writeln!(out);
        writeln!(out, "    /// Imperative native commands (`codegenNativeCommands`).");
        writeln!(out, "    pub mod commands {{");
        writeln!(out, "        use super::*;");
        for cmd in &spec.commands {
            let fn_name = rust_ident(&cmd.name);
            let mut sig = CodeWriter::new();
            for (idx, p) in cmd.params.iter().enumerate() {
                if idx > 0 {
                    sig.push_str(", ");
                }
                let pname = rust_ident(&p.name);
                let pty = rust_simple_type(&p.param_type);
                write!(sig, "{pname}: {pty}");
            }
            writeln!(out);
            writeln!(out, "        pub fn {fn_name}({sig}) -> Result<Vec<u8>, DecodeError> {{");
            if cmd.params.is_empty() {
                writeln!(out, "            Ok(Vec::new())");
            } else {
                emit_rust_bin_map_payload(&mut out, &cmd.params, "            ", false);
                writeln!(out, "            Ok(payload)");
            }
            writeln!(out, "        }}");
        }
        writeln!(out, "    }}");
    }

    writeln!(out, "}}");
    out.into_string()
}

pub(crate) fn emit_turbomodule_rust(spec: &TurboModuleSpec, mod_name: &str) -> String {
    let pascal = to_pascal_case(&spec.module_name);
    let mut out = CodeWriter::with_capacity(2048);

    writeln!(
        out,
        "// @generated by nve-codegen (`import_rn`) from React Native TurboModule `{}`.",
        sanitize_single_line_comment(&spec.module_name)
    );
    writeln!(out, "#![allow(dead_code, clippy::all)]");
    writeln!(out);
    writeln!(out, "pub mod {mod_name} {{");
    writeln!(
        out,
        "    use nve_abi::{{encode_bin_value_to_vec, DecodeError, NveMapEntry, NveValue, NveValueRef}};"
    );
    writeln!(out);
    writeln!(
        out,
        "    pub const MODULE_NAME: &str = \"{}\";",
        escape_c_like_string(&spec.module_name)
    );
    writeln!(out, "    pub const ENFORCING: bool = {};", spec.enforcing);
    writeln!(out);

    writeln!(
        out,
        "    /// Typed zero-JS host interface for TurboModule `{}`.",
        sanitize_single_line_comment(&spec.module_name)
    );
    writeln!(out, "    pub trait {pascal}Module {{");
    for method in &spec.methods {
        if let Some(doc) = &method.doc {
            for line in doc.lines() {
                writeln!(out, "        /// {}", sanitize_single_line_comment(line));
            }
        }
        let mname = rust_ident(&method.name);
        let mut params = CodeWriter::from(String::from("&self"));
        for p in &method.params {
            let pname = rust_ident(&p.name);
            let pty = rust_simple_type(&p.param_type);
            if p.optional {
                write!(params, ", {pname}: Option<{pty}>");
            } else {
                write!(params, ", {pname}: {pty}");
            }
        }
        let ret = rust_simple_type(&method.return_type);
        if ret == "()" {
            writeln!(out, "        fn {mname}({params});");
        } else {
            writeln!(out, "        fn {mname}({params}) -> {ret};");
        }
    }
    writeln!(out, "    }}");
    writeln!(out);

    writeln!(
        out,
        "    /// Binary `NveBinValue` payload encoder for TurboModule host calls."
    );
    writeln!(out, "    pub struct {pascal}Bridge;");
    writeln!(out);
    writeln!(out, "    impl {pascal}Bridge {{");
    for method in &spec.methods {
        let mname = rust_ident(&method.name);
        let mut params = CodeWriter::new();
        for (idx, p) in method.params.iter().enumerate() {
            if idx > 0 {
                params.push_str(", ");
            }
            let pname = rust_ident(&p.name);
            let pty = rust_simple_type(&p.param_type);
            if p.optional {
                write!(params, "{pname}: Option<{pty}>");
            } else {
                write!(params, "{pname}: {pty}");
            }
        }
        writeln!(out, "        pub fn {mname}({params}) -> Result<Vec<u8>, DecodeError> {{");
        if method.params.is_empty() {
            writeln!(out, "            Ok(Vec::new())");
        } else {
            emit_rust_bin_map_payload(&mut out, &method.params, "            ", true);
            writeln!(out, "            Ok(payload)");
        }
        writeln!(out, "        }}");
    }
    writeln!(out, "    }}");
    writeln!(out, "}}");
    out.into_string()
}

